a<-commandArgs(TRUE);if(length(a)<4)stop("Usage: cindex.R <devpred> <valpred> <out> <times>");if(!requireNamespace("survival",quietly=TRUE)||!requireNamespace("pec",quietly=TRUE))stop("Install survival and pec");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];tt<-as.numeric(strsplit(a[4],",",TRUE)[[1]]);mods<-intersect(setdiff(names(tr),c("ID","Time","Event")),names(va));dir.create(out,recursive=TRUE,showWarnings=FALSE);fits<-setNames(lapply(mods,function(m)survival::coxph(as.formula(paste("survival::Surv(Time,Event)~",m)),tr,x=TRUE,y=TRUE)),mods);global<-do.call(rbind,lapply(mods,function(m){q<-survival::concordance(survival::Surv(va$Time,va$Event)~I(-va[[m]]));data.frame(model=m,cindex=q$concordance,se=sqrt(q$var),lower=q$concordance-1.96*sqrt(q$var),upper=q$concordance+1.96*sqrt(q$var))}));write.csv(global,file.path(out,"validation_global_cindex.csv"),row.names=FALSE);ci<-pec::cindex(fits,formula=survival::Surv(Time,Event)~1,data=va,eval.times=tt);long<-data.frame(time=tt,ci$AppCindex,check.names=FALSE);write.csv(long,file.path(out,"validation_time_cindex_wide.csv"),row.names=FALSE);saveRDS(list(adapters=fits,cindex=ci),file.path(out,"cindex_objects.rds"))
